const assert = require('node:assert/strict');
const { Ledger } = require('../.build/ledger');
const { Transient } = require('../.build/transport');
const { PaymentService } = require('../.build/service');

class CountingLedger extends Ledger {
  applies = 0;
  async apply(tenant, key, cents) {
    this.applies++;
    return super.apply(tenant, key, cents);
  }
}

async function main() {
  // --- Ledger idempotency -------------------------------------------------
  {
    const ledger = new Ledger();
    const first = await ledger.apply('t', 'k', 100);
    const second = await ledger.apply('t', 'k', 100);
    assert.strictEqual(second, first, 'equal amount must return the original receipt');
    assert.equal(ledger.entries.length, 1, 'equal amount must not debit twice');
    assert.deepEqual(ledger.entries, [{ id: 1, tenant: 't', key: 'k', cents: 100 }]);

    await assert.rejects(ledger.apply('t', 'k', 200), (e) => e instanceof Error && e.message === 'key conflict');
    assert.equal(ledger.entries.length, 1, 'conflict must not debit');

    const other = await ledger.apply('t', 'k2', 100);
    assert.equal(other.id, 2, 'different key gets its own receipt');
    const otherTenant = await ledger.apply('t2', 'k', 100);
    assert.equal(otherTenant.id, 3, 'different tenant gets its own receipt');
    assert.equal(ledger.entries.length, 3);
  }

  // --- Concurrent ledger calls -------------------------------------------
  {
    const ledger = new Ledger();
    const [a, b] = await Promise.all([
      ledger.apply('t', 'k', 7),
      ledger.apply('t', 'k', 7),
    ]);
    assert.strictEqual(a, b, 'concurrent equal calls share the receipt');
    assert.equal(ledger.entries.length, 1, 'concurrent equal calls debit once');

    const conflict = new Ledger();
    const results = await Promise.allSettled([
      conflict.apply('t', 'k', 1),
      conflict.apply('t', 'k', 2),
    ]);
    assert.equal(conflict.entries.length, 1, 'concurrent conflict debits once');
    assert.equal(results.filter((r) => r.status === 'fulfilled').length, 1);
    assert.equal(results.find((r) => r.status === 'rejected').reason.message, 'key conflict');
  }

  // --- Retry only transient, forwarding the same receipt ------------------
  {
    const ledger = new CountingLedger();
    const forwarded = [];
    let calls = 0;
    const service = new PaymentService(ledger, {
      acknowledge: async (r) => {
        forwarded.push(r);
        if (++calls <= 2) throw new Transient('ack down');
      },
    });
    const receipt = await service.pay('shop', 'sale', 123, 3);
    assert.deepEqual(receipt, { id: 1, tenant: 'shop', key: 'sale', cents: 123 });
    assert.equal(calls, 3, 'should use up to attempts tries');
    assert.equal(ledger.entries.length, 1, 'retries must not duplicate the debit');
    assert.equal(ledger.applies, 1, 'a fetched receipt is reused on retries');
    for (const r of forwarded) assert.strictEqual(r, receipt, 'same receipt forwarded each try');
  }

  // --- Retry exhaustion preserves the final exception ---------------------
  {
    const ledger = new Ledger();
    const errors = [new Transient('first'), new Transient('second')];
    let calls = 0;
    const service = new PaymentService(ledger, {
      acknowledge: async () => { throw errors[calls++]; },
    });
    try {
      await service.pay('t', 'k', 5, 2);
      assert.fail('expected failure');
    } catch (e) {
      assert.strictEqual(e, errors[1], 'must throw the final transient');
    }
    assert.equal(calls, 2, 'attempts caps total tries');
    assert.equal(ledger.entries.length, 1, 'debit committed exactly once');
  }

  // --- Non-transient errors are not retried -------------------------------
  {
    const ledger = new Ledger();
    const boom = new Error('boom');
    let calls = 0;
    const service = new PaymentService(ledger, { acknowledge: async () => { calls++; throw boom; } });
    await assert.rejects(service.pay('t', 'k', 5, 5), (e) => e === boom);
    assert.equal(calls, 1, 'non-transient must not be retried');
    assert.equal(ledger.entries.length, 1);
  }

  // --- Transient from apply is retried too --------------------------------
  {
    const real = new Ledger();
    const flaky = {
      calls: 0,
      async apply(tenant, key, cents) {
        if (++this.calls === 1) throw new Transient('ledger hiccup');
        return real.apply(tenant, key, cents);
      },
    };
    const service = new PaymentService(flaky, { acknowledge: async () => {} });
    const receipt = await service.pay('t', 'k', 9, 3);
    assert.equal(receipt.id, 1);
    assert.equal(real.entries.length, 1);
  }

  // --- Validation happens before ledger/transport action ------------------
  {
    const ledger = new CountingLedger();
    let acks = 0;
    const service = new PaymentService(ledger, { acknowledge: async () => { acks++; } });
    const bad = [
      ['', 'k', 1, 3], [null, 'k', 1, 3], [5, 'k', 1, 3],
      ['t', '', 1, 3], ['t', null, 1, 3],
      ['t', 'k', 0, 3], ['t', 'k', -1, 3], ['t', 'k', 1.5, 3],
      ['t', 'k', NaN, 3], ['t', 'k', '1', 3],
      ['t', 'k', 1, 0], ['t', 'k', 1, 6], ['t', 'k', 1, 1.5],
      ['t', 'k', 1, NaN],
    ];
    for (const args of bad) {
      await assert.rejects(service.pay(...args), (e) => e instanceof Error && e.message === 'invalid payment');
    }
    assert.equal(ledger.applies, 0, 'no ledger action for invalid input');
    assert.equal(acks, 0, 'no transport action for invalid input');
    const ok = await service.pay('t', 'k', 1);
    assert.equal(ok.id, 1, 'default attempts still works');
  }

  // --- Concurrent service calls, same key/amount --------------------------
  {
    const ledger = new Ledger();
    const service = new PaymentService(ledger, { acknowledge: async () => {} });
    const [a, b] = await Promise.all([
      service.pay('t', 'k', 11, 3),
      service.pay('t', 'k', 11, 3),
    ]);
    assert.strictEqual(a, b);
    assert.equal(ledger.entries.length, 1);
  }

  console.log('idempotency checks OK');
}

module.exports = main();
EOF
